import{_ as e,c as a,o as r,ag as l}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"Telegraph 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/telegraph.md","filePath":"platforms/telegraph.md","lastUpdated":1790228279000}'),o={name:"platforms/telegraph.md"};function d(i,t,h,s,n,c){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="telegraph-配置指南" tabindex="-1">Telegraph 配置指南 <a class="header-anchor" href="#telegraph-配置指南" aria-label="Permalink to &quot;Telegraph 配置指南&quot;">​</a></h1><p>通过 <strong>Telegraph</strong> 发布到 Telegra.ph 页面。Telegraph 为 <strong>CORS 受限平台</strong>（域名被网络环境阻断），必须填写你自己的 <strong>CORS 代理地址</strong> 才能正常访问，且支持 <strong>匿名发布</strong> 与 <strong>登录发布</strong> 两种模式。</p><h2 id="一、前置说明" tabindex="-1">一、前置说明 <a class="header-anchor" href="#一、前置说明" aria-label="Permalink to &quot;一、前置说明&quot;">​</a></h2><ol><li>Telegra.ph 是一个网页平台，非开放 API；本插件通过其网页表单端点（<code>/check</code>、<code>/save</code>）发布。</li><li><strong>必须配置 CORS 代理</strong>：Telegra.ph 域名在部分网络环境下无法直连，需通过你自己的 CORS 代理转发。切勿依赖共享代理（不再免费提供，且易被滥用）。</li><li>支持两种发布模式，配置页通过「登录模式」切换。</li></ol><h2 id="二、匿名发布" tabindex="-1">二、匿名发布 <a class="header-anchor" href="#二、匿名发布" aria-label="Permalink to &quot;二、匿名发布&quot;">​</a></h2><p>匿名发布无需 Telegraph 账号，适合快速生成可分享的轻量文章。</p><ol><li>在配置页「登录模式」选 <strong>匿名发布</strong>。</li><li>平台首页、API 地址保持默认（<code>https://telegra.ph</code>、<code>https://edit.telegra.ph</code>）。</li><li>「新代理」填写你自己的 CORS 代理地址。</li><li>点「验证」——插件自动调用 <code>/check</code> 获取 <strong>Uuid</strong> 与 <strong>Hash</strong> 并保存。</li><li>验证通过后即可发布；文章为匿名，作者可自定义（默认为空）。</li></ol><h2 id="三、登录发布" tabindex="-1">三、登录发布 <a class="header-anchor" href="#三、登录发布" aria-label="Permalink to &quot;三、登录发布&quot;">​</a></h2><p>登录发布将文章归入你的 Telegraph 账号。</p><ol><li>在配置页「登录模式」选 <strong>登录发布</strong>。</li><li>从浏览器开发者工具读取以下字段并填写： <ul><li><strong>Access Token</strong>：Telegraph 账号的 token。</li><li><strong>Uuid</strong>：<code>tph_uuid</code> 的值。</li><li><strong>Hash</strong>：<code>save hash</code>。</li></ul></li><li>「新代理」填写你自己的 CORS 代理地址。</li><li>点「验证」通过后即可发布。</li></ol><h2 id="四、获取-uuid-hash-匿名模式" tabindex="-1">四、获取 Uuid / Hash（匿名模式） <a class="header-anchor" href="#四、获取-uuid-hash-匿名模式" aria-label="Permalink to &quot;四、获取 Uuid / Hash（匿名模式）&quot;">​</a></h2><ul><li>匿名模式下，验证（<code>/check</code>）会自动获取并保存 Uuid 与 Hash，无需手动填写。</li><li>若切换设备（含从 PC 到浏览器环境），需重新验证并获取新 Uuid/Hash。</li></ul><h2 id="五、字段说明" tabindex="-1">五、字段说明 <a class="header-anchor" href="#五、字段说明" aria-label="Permalink to &quot;五、字段说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>通常固定 <code>https://telegra.ph</code>，保持默认</td></tr><tr><td>API 地址</td><td>通常固定 <code>https://edit.telegra.ph</code>，保持默认</td></tr><tr><td>登录模式</td><td>匿名发布 / 登录发布，按需切换</td></tr><tr><td>作者</td><td>显示在文章详情，可自定义，默认为空</td></tr><tr><td>Uuid</td><td>匿名模式验证自动获取；登录模式手动填 <code>tph_uuid</code></td></tr><tr><td>Hash</td><td>匿名模式验证自动获取；登录模式手动填 <code>save hash</code></td></tr><tr><td>预览规则</td><td>固定 <code>/[postid]</code>，不可修改；查看链接通过 CORS 代理访问</td></tr><tr><td>新代理(CORS)</td><td>必填：你自己的 CORS 代理地址，例如 <code>https://cors.yourdomain.com</code></td></tr></tbody></table><h2 id="六、验证与发布" tabindex="-1">六、验证与发布 <a class="header-anchor" href="#六、验证与发布" aria-label="Permalink to &quot;六、验证与发布&quot;">​</a></h2><ol><li>配置页点「验证」→ 连通性测试通过（匿名自动获取 Uuid/Hash）。</li><li>快速发布 → 选 Telegraph → 发布。</li><li>发布后「查看文章」通过你的 CORS 代理打开 Telegra.ph 页面。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「需要配置 CORS 代理地址」</strong>：Telegraph 为 CORS 受限平台，请在「新代理」填写你自己的 CORS 代理地址。</li><li><strong>提示「telegra.ph 请求错误」</strong>：多为 CORS 代理不可用或 Uuid/Hash 失效，重新验证或更换代理。</li><li><strong>切换设备后发布失败</strong>：Telegraph 的 Uuid/Hash 与设备绑定，需重新验证获取新值。</li><li><strong>支持图片上传吗</strong>：暂不支持。Telegra.ph 不提供平台图片上传，建议配合本地或图床方案。</li><li><strong>查看文章打不开</strong>：确认你的 CORS 代理可访问，且当前网络可连到该代理。</li></ul>',18)])])}const u=e(o,[["render",d]]);export{p as __pageData,u as default};
